'use strict';

// MODULES //

var promotionRules = require( '@stdlib/ndarray/promotion-rules' );
var dtypes = require( '@stdlib/ndarray/dtypes' );
var dtypeChar = require( '@stdlib/ndarray/base/dtype-char' );
var cartesianProduct = require( '@stdlib/array/cartesian-product' );
var format = require( '@stdlib/string/format' );
var config = require( '@stdlib/math/special/ceil/scripts/config.js' );
var generateTable = require( '@stdlib/math/special/ceil/scripts/table.js' );


// MAIN //

/**
* Generate dtype pairs, match them with stdlib packages, and resolve C function names and loop kernels.
*
* ## Note
*
* -   The function generates an array of matches, where each match is an array in the format:
*
* ```text
*             ----------------------------------------------------------------------------------------------------------------------------------------
*  Array:    | input_dtype | output_dtype | package | needs_to_promote | promoted_input_dtype | promoted_output_dtype | c_function_name | loop_kernel |
*             ----------------------------------------------------------------------------------------------------------------------------------------
*                   |              |           |            |                     |                      |                      |              |
*                   |              |           |            |                     |                      |                      |              |
*                   V              V           |            V                     V                      V                      |              V
*  Example:     'float32'       'float32'      |           true               'float64'              'float64'                  |       'stdlib_ndarray_f_f'
*                                              V                                                                                V
*                               '@stdlib/math/base/special/expf'                                                         'stdlib_base_expf'
* ```
*
* @private
* @returns {Array} matches table containing dtype pairs and their corresponding package information
*/
function main() {
	var functionName;
	var matches = [];
	var basePkg;
	var kernel;
	var table;
	var pairs;
	var pkg;
	var pdt;
	var row;
	var idt;
	var odt;
	var dt;
	var i;
	var j;

	// Generate the table:
	pkg = require( '@stdlib/math/special/ceil/package.json' );
	basePkg = pkg.name.split( '/' ).pop();
	table = generateTable( basePkg );

	/*
		Should be generated in this order only. Check once:
		Table: [
			[ 'float32', 'float32', '@stdlib/math/base/special/ceilf' ],
			[ 'float64', 'float64', '@stdlib/math/base/special/ceil' ],
			[ 'complex64', 'complex64', '@stdlib/math/base/special/cceilf' ]
			[ 'complex128', 'complex128', '@stdlib/math/base/special/cceil' ],
		]
	*/

	/*
		Resolve list of input dtypes. After this, we'll have:
		idt = [
			'complex32',
			'complex64',
			'complex128',
			'float16',
			'float32',
			'float64',
			'int32',
			'int16',
			'int8',
			'uint32',
			'uint16',
			'uint8',
			'uint8c'
		]
	*/
	idt = dtypes( config.input_dtypes );

	/*
		Resolve the list of output dtypes. After this, we'll have:
		odt = [
			'complex32',
			'complex128',
			'complex64',
			'float16',
			'float64',
			'float32',
			'int32',
			'int16',
			'int8',
			'uint32',
			'uint16',
			'uint8',
			'uint8c'
		]
	*/
	odt = dtypes( config.output_dtypes );

	/*
		Generate the input-output dtype pairs. After this, we'll have:
		pairs = [
			[ 'complex32', 'complex32' ],
			[ 'complex32', 'complex64' ],
			[ 'complex32', 'complex128' ],
			[ 'complex32', 'float16' ],
			[ 'complex32', 'float32' ],
			[ 'complex32', 'float64' ],
			[ 'complex32', 'int32' ],
			[ 'complex32', 'int16' ],
			[ 'complex32', 'int8' ],
			[ 'complex32', 'uint32' ],
			[ 'complex32', 'uint16' ],
			[ 'complex32', 'uint8' ],
			[ 'complex32', 'uint8c' ],
			[ 'complex64', 'complex32' ],
			[ 'complex64', 'complex64' ],
			[ 'complex64', 'complex128' ],
			[ 'complex64', 'float16' ],
			[ 'complex64', 'float32' ],
			[ 'complex64', 'float64' ],
			[ 'complex64', 'int32' ],
			...
		]
	*/
	pairs = cartesianProduct( idt, odt );

	// Match-make each dtype pair with a stdlib package...
	for ( i = 0; i < pairs.length; i++ ) {
		// Now let dt = [ 'complex32', 'float32' ]...
		dt = pairs[ i ];

		// First pass: look for exact matches...
		for ( j = 0; j < table.length; j++ ) {
			// Now let row = [ 'complex64', 'complex64', '@stdlib/math/base/special/cceilf' ]...
			row = table[ j ];
			if ( row[ 0 ] === dt[ 0 ] && row[ 1 ] === dt[ 1 ] ) {
				matches.push( [ dt[ 0 ], dt[ 1 ], row[ 2 ], false, null, null, '', '' ] );
				break;
			}

			// Next check for package to which the dtype pair can promote...
			// For example, pdt = promotionRules( 'complex32', 'complex64' ) = 'complex64'
			pdt = promotionRules( dt[ 0 ], row[ 0 ] );
			if ( pdt ) {
				// Check for a package which supports the promoted dtypes...
				if ( row[ 0 ] === pdt && row[ 1 ] === pdt ) {
					matches.push( [ dt[ 0 ], dt[ 1 ], row[ 2 ], true, pdt, pdt, '', '' ] );
					break;
				}
			}
		}
	}

	// NOTE: modify below to also resolve JS alias for generating the JavaScript tables, as well...
	// Resolve the scalar math kernel C function name...
	for ( i = 0; i < matches.length; i++ ) {
		row = matches[ i ];

		// Extract function name from package path (e.g., '@stdlib/math/base/special/ceilf' -> 'ceilf')
		functionName = row[ 2 ].split( '/' ).pop();
		row[ 6 ] = 'stdlib_base_' + functionName;
	}

	// Resolve the loop kernel...
	for ( i = 0; i < matches.length; i++ ) {
		row = matches[ i ];
		if ( row[ 3 ] === true ) {
			kernel = format( 'stdlib_ndarray_%s_%s_as_%s_%s', dtypeChar( row[ 0 ] ), dtypeChar( row[ 1 ] ), dtypeChar( row[ 4 ] ), dtypeChar( row[ 5 ] ) );
		} else {
			kernel = format( 'stdlib_ndarray_%s_%s', dtypeChar( row[ 0 ] ), dtypeChar( row[ 1 ] ) );
		}
		row[ 7 ] = kernel;
	}

	return matches;
}

module.exports = main;
